def fibonacci(n):
    if n < 2:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

#include <vector>

std::vector<float> normalize(std::vector<float> v) {
    float n = 0.0f;
    for (float x : v) n += x * x;
    n = std::sqrt(n);
    for (float & x : v) x /= n;
    return v;
}

